body.script:
(function () {
    var id = new URLSearchParams(location.search).get("id");

    if (!id) {
        document.title = "PDF Document";
        document.body.innerHTML = "
No document ID provided.";
        return;
    }

    document.title = id + " - PDF Document";

    location.href = "./pdfs/" + encodeURIComponent(id) + ".pdf";
})();
